// At most two questions, each answerable in a sentence. A six-question form does not get
// answered; it gets ignored, and the run dies quietly.
const qs = ($json.payload.questions || []).slice(0, 2);
const partial = $json.payload.partial_brief || {};
const understood = [partial.objective && `objective: ${partial.objective}`, partial.offer?.name && `offer: ${partial.offer.name}`, (partial.channels || []).length && `channels: ${partial.channels.map(c => c.channel).join(', ')}`].filter(Boolean).join(' | ');
return [{ json: {
  text: `I can start on this, but I'd get it wrong without ${qs.length > 1 ? 'two answers' : 'one answer'}.\n\nWhat I have: ${understood || 'not much yet'}\n\n${qs.map((q, i) => `${i + 1}. ${q}`).join('\n')}`,
  questions: qs,
  partial_brief: partial
} }];
